def add_quebec_voices(apps, schema_editor):
    """Distribution existante : ajoute les voix québécoises de départ (7.2) sans toucher au reste."""
    SiteSettings = apps.get_model("usage", "SiteSettings")
    for site in SiteSettings.objects.all():
        casting = dict(site.tts_casting or {})
        changed = False
        for key, voices in QUEBEC_VOICES.items():
            if not casting.get(key):
                casting[key] = voices
                changed = True
        if changed:
            site.tts_casting = casting
            site.save(update_fields=["tts_casting"])


